import type { Command } from "foldkit";
import { Ui } from "foldkit";

export const { Model } = Ui.RadioGroup;
export type Model = Ui.RadioGroup.Model;

export type Orientation = Ui.RadioGroup.Orientation;

export const { SelectedOption } = Ui.RadioGroup;
export const { CompletedFocusOption } = Ui.RadioGroup;
export const { Message } = Ui.RadioGroup;
export type SelectedOption = Ui.RadioGroup.SelectedOption;
export type CompletedFocusOption = Ui.RadioGroup.CompletedFocusOption;
export type Message = Ui.RadioGroup.Message;

export const { Selected } = Ui.RadioGroup;
export const { OutMessage } = Ui.RadioGroup;
export type Selected<Value extends string = string> =
  Ui.RadioGroup.Selected<Value>;
export type OutMessage<Value extends string = string> =
  Ui.RadioGroup.OutMessage<Value>;

export type InitConfig = Ui.RadioGroup.InitConfig;
export type Commands = readonly Command.Command<Message>[];
export type InitReturn = readonly [Model, Commands];

export type OptionInfo<Value extends string = string> =
  Ui.RadioGroup.OptionInfo<Value>;
export type RenderInfo<Value extends string = string> =
  Ui.RadioGroup.RenderInfo<Value>;
export type ViewInputs<Value extends string = string> =
  Ui.RadioGroup.ViewInputs<Value>;

export const init = (config: InitConfig): InitReturn => [
  Ui.RadioGroup.init(config),
  [],
];

export const { FocusOption } = Ui.RadioGroup;
export const { create } = Ui.RadioGroup;

export {
  checkIcon,
  checkPlaceholder,
  descriptionClassName,
  horizontalGroupClassName,
  horizontalOptionClassName,
  labelClassName,
  metaClassName,
  verticalGroupClassName,
  verticalOptionClassName,
} from "./view";

import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

export const verticalGroupClassName = "flex w-full flex-col gap-3";

export const horizontalGroupClassName =
  "flex w-full flex-col gap-3 sm:flex-row";

export const verticalOptionClassName =
  "relative flex cursor-pointer rounded-lg border border-gray-200 p-4 transition-colors hover:bg-gray-50 data-[checked]:border-accent-600 data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50 focus:outline-none focus:ring-2 focus:ring-accent-500 focus:ring-offset-2";

export const horizontalOptionClassName =
  "relative flex flex-1 cursor-pointer rounded-lg border border-gray-200 p-4 transition-colors hover:bg-gray-50 data-[checked]:border-accent-600 data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50 focus:outline-none focus:ring-2 focus:ring-accent-500 focus:ring-offset-2";

export const labelClassName = "text-sm font-medium text-gray-900";

export const descriptionClassName = "text-sm text-gray-600";

export const metaClassName = "text-sm font-semibold text-accent-600";

export const checkIcon = (): Html => {
  const h = html();

  return h.svg(
    [h.ViewBox("0 0 24 24"), h.Fill("none"), h.Class("size-5 text-accent-600")],
    [
      h.path(
        [
          h.D("M9 12.75L11.25 15 15 9.75M21 12a9 9 0 11-18 0 9 9 0 0118 0z"),
          h.Stroke("currentColor"),
          h.StrokeWidth("1.5"),
          h.StrokeLinecap("round"),
          h.StrokeLinejoin("round"),
        ],
        []
      ),
    ]
  );
};

export const checkPlaceholder = (): Html => {
  const h = html();

  return h.div([h.Class("size-5")], []);
};

import { Match as M, Option, Schema as S } from "effect";
import { Command, Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";
import { describe, test } from "vitest";

import * as RadioGroup from "./index";

type Plan = "Startup" | "Business" | "Enterprise";

const PlanRadioGroup = RadioGroup.create<Plan>();
const plans: readonly Plan[] = ["Startup", "Business", "Enterprise"];

const GotRadioGroupMessage = m("GotRadioGroupMessage", {
  message: RadioGroup.Message,
});

const Model = S.Struct({
  radioGroup: RadioGroup.Model,
});

type Model = typeof Model.Type;

const Message = S.Union([GotRadioGroupMessage]);
type Message = typeof Message.Type;

const initialModel: Model = {
  radioGroup: RadioGroup.init({
    id: "plan-radio-group",
    selectedValue: "Startup",
  })[0],
};

const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      GotRadioGroupMessage: ({ message }) => {
        const [radioGroup, radioGroupCommands] = PlanRadioGroup.update(
          model.radioGroup,
          message
        );

        return [
          evo(model, { radioGroup: () => radioGroup }),
          Command.mapMessages(radioGroupCommands, (message) =>
            GotRadioGroupMessage({ message })
          ),
        ];
      },
    })
  );

const selectedLabel = (model: Model): string =>
  Option.getOrElse(model.radioGroup.selectedValue, () => "none");

const view = (model: Model): Html => {
  const h = html<Message>();

  return h.div(
    [h.Class("space-y-3")],
    [
      h.submodel({
        slotId: model.radioGroup.id,
        model: model.radioGroup,
        view: PlanRadioGroup.view,
        viewInputs: {
          options: plans,
          ariaLabel: "Server plan",
          name: "plan",
          toView: ({ group, hiddenInput, options }) =>
            h.div(
              [...group, h.Class(RadioGroup.verticalGroupClassName)],
              [
                h.input(hiddenInput),
                ...options.map((option) =>
                  h.div(
                    [
                      ...option.option,
                      h.Class(RadioGroup.verticalOptionClassName),
                    ],
                    [
                      h.div(
                        [h.Class("flex w-full items-center justify-between")],
                        [
                          h.div(
                            [],
                            [
                              h.span(
                                [
                                  ...option.label,
                                  h.Class(RadioGroup.labelClassName),
                                ],
                                [option.value]
                              ),
                              h.p(
                                [
                                  ...option.description,
                                  h.Class(RadioGroup.descriptionClassName),
                                ],
                                [`${option.value} plan`]
                              ),
                            ]
                          ),
                          option.isSelected
                            ? RadioGroup.checkIcon()
                            : RadioGroup.checkPlaceholder(),
                        ]
                      ),
                    ]
                  )
                ),
              ]
            ),
        },
        toParentMessage: (message) => GotRadioGroupMessage({ message }),
      }),
      h.p([], [`Selected plan: ${selectedLabel(model)}`]),
    ]
  );
};

const disabledView = (model: Model): Html => {
  const h = html<Message>();

  return h.submodel({
    slotId: "disabled-plan-radio-group",
    model: model.radioGroup,
    view: PlanRadioGroup.view,
    viewInputs: {
      options: plans,
      ariaLabel: "Locked server plan",
      isDisabled: true,
      toView: ({ group, options }) =>
        h.div(
          [...group, h.Class(RadioGroup.verticalGroupClassName)],
          options.map((option) =>
            h.div(
              [...option.option, h.Class(RadioGroup.verticalOptionClassName)],
              [
                h.span(
                  [...option.label, h.Class(RadioGroup.labelClassName)],
                  [option.value]
                ),
              ]
            )
          )
        ),
    },
    toParentMessage: (message) => GotRadioGroupMessage({ message }),
  });
};

describe("RadioGroup registry view", () => {
  test("renders options, hidden input, and selection messages", () => {
    Scene.scene(
      { update, view },
      Scene.with(initialModel),
      Scene.expect(Scene.role("radio", { name: "Startup" })).toBeChecked(),
      Scene.expect(Scene.text("Startup plan")).toExist(),
      Scene.click(Scene.role("radio", { name: "Business" })),
      Scene.Command.expectHas(
        RadioGroup.FocusOption({ id: "plan-radio-group", index: 1 })
      ),
      Scene.Command.resolve(
        RadioGroup.FocusOption({ id: "plan-radio-group", index: 1 }),
        RadioGroup.CompletedFocusOption(),
        (message) => GotRadioGroupMessage({ message })
      ),
      Scene.expect(Scene.role("radio", { name: "Business" })).toBeChecked(),
      Scene.expect(Scene.text("Selected plan: Business")).toExist()
    );
  });

  test("supports disabled group state", () => {
    Scene.scene(
      { update, view: disabledView },
      Scene.with(initialModel),
      Scene.expect(Scene.role("radio", { name: "Startup" })).toBeDisabled(),
      Scene.expect(Scene.role("radio", { name: "Business" })).toBeDisabled()
    );
  });
});
